/**
 * reportFonts.ts — PDF raporu için gömülü Unicode font (Türkçe karakter desteği).
 *
 * jsPDF'in yerleşik fontları (helvetica/times/courier) yalnızca WinAnsi/Latin-1
 * alt kümesini destekler; Türkçe karakterler (ÇĞİıÖŞÜ vb.) için TrueType font
 * gömülmesi gerekir. Burada kullanılan DejaVu Sans, Bitstream Vera Fonts
 * lisansı altında serbestçe kullanılabilir, değiştirilebilir ve dağıtılabilir
 * bir açık kaynak fonttur (ticari kullanım dahil kısıtlama yoktur).
 *
 * Kaynak: https://dejavu-fonts.github.io/ (npm: dejavu-fonts-ttf@2.37.3)
 * Lisans: Bitstream Vera Fonts Copyright + Arev Fonts Copyright (serbest/free,
 *         detaylar için https://dejavu-fonts.github.io/License.html)
 *
 * Bundle boyutunu küçültmek için font, uygulamanın gerçekten kullandığı karakter
 * kümesine (temel Latin + Latin-1 + Latin Extended-A + birkaç noktalama/sembol)
 * fonttools/pyftsubset ile alt kümelenmiştir (orijinal ~730KB/font → ~58KB/font).
 * Yeniden üretmek için:
 *   pyftsubset DejaVuSans.ttf --output-file=DejaVuSans-subset.ttf \
 *     --unicodes="U+0020-007E,U+00A0-00FF,U+0100-017F,U+2013-2014,U+2018-201E,U+20AC,U+2212"
 * (aynı komut DejaVuSans-Bold.ttf için de uygulanır.)
 */

/** DejaVu Sans (normal), base64 TTF — alt kümelenmiş. */
export const DEJAVU_SANS_NORMAL_B64 = "";

/** DejaVu Sans Bold, base64 TTF — alt kümelenmiş. */
export const DEJAVU_SANS_BOLD_B64 = "";
